-- 165: Original BrillaPrep WASSCE BrillaPrep transitional Building Construction beta content blueprint questions, part 2.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_165_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_165_guard;
INSERT INTO _migration_165_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_006' AND NOT (q.topic_id IS 'topic_was_building_b003_2' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What field test gives a quick indication of the workability of fresh concrete?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The crushing test","B. The slump test","C. The sieve analysis of hardened concrete","D. The soundness test for bricks"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The slump test measures the deformation of freshly compacted concrete under its own weight and gives a practical consistency check for a batch. Therefore the correct answer is B: The slump test.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_006' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_165_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_007' AND NOT (q.topic_id IS 'topic_was_building_b003_2' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should cement bags be stored on a raised dry platform?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. To increase the cement particle size","B. To make each bag chemically stronger with age","C. To prevent moisture absorption and premature hydration","D. To allow rainwater to cool the cement"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Cement reacts with moisture and can form hard lumps or lose binding capacity, so dry enclosed storage above the floor preserves quality. Therefore the correct answer is C: To prevent moisture absorption and premature hydration.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_2' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_007' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_165_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_008' AND NOT (q.topic_id IS 'topic_was_building_b003_2' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which property makes well-fired clay bricks suitable for external walling?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Complete flexibility under load","B. High solubility in rainwater","C. Zero dimensional variation in manufacture","D. Adequate strength with durable resistance to weathering"]' AND q.correct_answer IS 'D' AND q.explanation IS 'External masonry units must carry imposed loads and resist repeated wetting and drying without rapid decay or excessive water damage. Therefore the correct answer is D: Adequate strength with durable resistance to weathering.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_008' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 