ack_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_165_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_010' AND NOT (q.topic_id IS 'topic_was_building_b003_2' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is clean water specified for mixing structural concrete?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Clean water prevents cement from hydrating","B. Contaminants can interfere with setting, strength and reinforcement durability","C. Dirty water always increases early strength","D. Water quality affects colour only"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Excess salts, oils, acids or organic matter may disrupt hydration or encourage corrosion, making potable-quality water a reliable default. Therefore the correct answer is B: Contaminants can interfere with setting, strength and reinforcement durability.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_2' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_010' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
